const BLUE='#6478ef',PINK='#f18db3',MINT='#69bfb2',GOLD='#e7cc58';const B=(x,y,z,c=BLUE)=>({x,y,z,c});const line=(x,y,z,dx,dy,dz,n,c=BLUE)=>Array.from({length:n},(_,i)=>B(x+i*dx,y+i*dy,z+i*dz,c));const solid=(nx,ny,nz,c=BLUE)=>Array.from({length:nx*ny*nz},(_,i)=>B(i%nx,Math.floor(i/nx)%ny,Math.floor(i/(nx*ny)),c));
// Fixed-view anamorphoses: adding (t,t,t) preserves the projected position.
const uniqueBlocks=bs=>[...new Map(bs.map(b=>[`${b.x},${b.y},${b.z}`,b])).values()];
function cubePath(points,c=BLUE){const bs=[];for(let j=0;j<points.length-1;j++){const a=points[j],b=points[j+1],n=Math.max(...a.map((v,i)=>Math.abs(b[i]-v)));for(let k=0;k<=n;k++)bs.push(B(...a.map((v,i)=>v+(b[i]-v)*k/n),c))}return uniqueBlocks(bs)}
function opticalHex(n,t=1){return uniqueBlocks([...cubePath([[0,0,n],[n,0,n],[n,0,0],[n,n,0],[0,n,0]],BLUE),...cubePath([[t,n+t,t],[t,n+t,n+t],[t,t,n+t]],PINK)])}
function opticalCube(n,t=1){const bs=[];for(let x=0;x<=n;x++)for(let y=0;y<=n;y++)for(let z=0;z<=n;z++)if([x,y,z].filter(v=>v===0||v===n).length>=2){if(y===0&&z===n&&x>0&&x<n)continue;bs.push(B(x,y,z))}bs.push(...cubePath([[t,t,n+t],[n+t,t,n+t]],PINK));return uniqueBlocks(bs)}
function neckerCube(n=4){const bs=[];for(let x=0;x<=n;x++)for(let y=0;y<=n;y++)for(let z=0;z<=n;z++)if([x,y,z].filter(v=>v===0||v===n).length>=2)bs.push(B(x,y,z));return uniqueBlocks(bs)}
function impossibleSquare(n=5){return uniqueBlocks([...cubePath([[0,0,0],[n,0,0],[n,n,0],[0,n,0]],BLUE),...cubePath([[0,n,0],[n,n,n]],PINK)])}
function reutersTriangle(n=5){return uniqueBlocks([...cubePath([[0,0,0],[n,0,0]],BLUE),...cubePath([[n,0,0],[n,n,0]],PINK),...cubePath([[n,n,0],[n,n,n]],MINT)])}
function penroseStairs(n=4){const bs=[];const addFlight=(sx,sy,dx,dy,base,c)=>{for(let i=0;i<n;i++)for(let z=0;z<=base+i;z++)bs.push(B(sx+i*dx,sy+i*dy,z,c))};addFlight(0,0,1,0,0,BLUE);addFlight(n-1,1,0,1,1,PINK);addFlight(n-2,n-1,-1,0,2,MINT);addFlight(0,n-2,0,-1,3,GOLD);return uniqueBlocks(bs)}
